// export default Datepickk


function DropDownList() {

    const MIN_WIDTH = 160;

    this.width = 0; // 0 - береться ширина по контейнеру інакше задана ширина

    let positionCoord = function (e) { // отримати позицію форми вводу

        let box = e.getBoundingClientRect();
        let width = this.width;

        return {
            bottom: box.bottom + window.pageYOffset,
            left: box.left + window.pageXOffset,
            right: box.right + window.pageXOffset - (width ? width : MIN_WIDTH),
            width: (width ? width : box.width)
        }

    }.bind(this);

    function handleTarget() {

        let target = document.querySelector(":focus");

        if (target && !removeList()) {

            removeList();
            let parent = target.parentNode;

            if (!parent.matches('.menu-content__group')) return; // якщо не наш INPUT не цікавить

            let data = JSON.parse(parent.getAttribute('data-params'));
            let selected = parent.getAttribute('data-selected');
            let url = parent.getAttribute('data-url');
            if (target.tagName == "SPAN") {
                removeList();
            }
            if (!data || !url) return; // якщо даних немає список не формуємо

            let box = createList(data, url, selected, positionCoord(parent));

            searchList(target, box);
            selectedList(target, box);

        } else {
            setTimeout(function () {
                    if (target) target.blur();
                    removeList();
                }, 100
            )
        }
    }

    function selectedList(target, box) {
        target.addEventListener('keyup', function (e) {
            if (e.keyCode === 13) {
                let elems = box.querySelectorAll('.line');
                for (let key in elems) {
                    if (!elems.hasOwnProperty(key)) continue;
                    let inputText = elems[key];


                    let index = inputText.textContent.indexOf(this.value);

                    if (index >= 0 && this.value != " " && this.value != null) {
                        if (this.value.length == 0) {
                            location.reload();
                        }
                        else inputText.click();
                        return; // ранее была закомментирована данная строка. Необходимо уточнить в чем была причина данного решения, потому что без него урл успевает измениться на последний найденный по совпадениям, что приводит к нажатию на последний элемент в списке, а не на первый, как необходимо. (с) Никита Кобзарь
                    }
                }
            }
        });
    }

    function searchList(target, box) {

        target.addEventListener('input', function () {

            let elems = box.querySelectorAll('.line');
            let len = this.value.length;

            for (let key in elems) {
                if (!elems.hasOwnProperty(key)) continue;

                let inputText = elems[key];

                inputText.parentNode.style.display = 'inline';

                let innerHTML = inputText.textContent;
                let index = innerHTML.indexOf(this.value);

                if (index >= 0) {
                    innerHTML = innerHTML.substring(0, index) + "<span class='highlight'>" + innerHTML.substring(index, index + len) + "</span>" + innerHTML.substring(index + len);
                    inputText.innerHTML = innerHTML;
                } else {
                    inputText.parentNode.style.display = 'none';
                }
            }
        });
    }

    function createList(data, url, selected, box) {
        let li = '';
        let div = document.createElement('div');

        for (let key in data) {
            if (!data.hasOwnProperty(key)) continue;

            // так .. тому що понапридумували непотрібних гет параметрів типу -1.
            let rKEY = key === '0' ? '-1' : key;

            li += '<li ' + (selected === rKEY ? 'class="selected"' : '') + '><a href="' + url.replace(/%7E%7E/g, rKEY) + '" class="line js-pjax">' + data[key] + '</a></li>';
        }

        div.style.top = box.bottom + 'px';
        div.style.left = box.right + 'px';
        div.style.width = box.width + 'px';

        div.className = "menu-content__list";
        div.id = "list-dropdown-status-id";
        div.innerHTML = "<ul>" + li + "</ul>";

        document.body.appendChild(div);

        return div;
    }

    function removeList() {
        let elem = document.querySelector('.menu-content__list');
        if (elem) {
            document.body.removeChild(elem);
            return true;
        }
        else return false;
    }

    this.create = function () {
        document.body.addEventListener('click', handleTarget);
    }
}

var list = new DropDownList();

list.width = 180;
list.create();
// для того щоб без перезавантаження відрацьовувала сторінка при виборі статусу
$(document).on('click', '.js-pjax', function(e){
    e.preventDefault();
    var $this = $(this);
    var href = $this.attr('href');
    $.pjax.reload({container:'#outagesGrid', url:href});
    return false;
});

